from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    q = deque([start])
    visited = {start}
    parent = {}

    while q:
        curr = q.popleft()

        if curr == goal:
            path = []
            while curr != start:
                path.append(curr)
                curr = parent[curr]
            path.append(start)
            return path[::-1]

        row, col = curr

        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for nr, nc in neighbors:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                q.append((nr, nc))
                visited.add((nr, nc))
                parent[(nr, nc)] = curr

    return []
