        return [start]

    q = deque([start])
    visited = {start}
    parent = {}

    while q:
        curr = q.popleft()

        row, col = curr

        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for nr, nc in neighbors:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                q.append((nr, nc))
                visited.add((nr, nc))
                parent[(nr, nc)] = curr

    if goal not in visited:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)

    return path[::-1]
